-- Function: public.fn_get_branches_for_benchmarking
-- Backup generated on 2026-11-11 09:04:48

CREATE OR REPLACE FUNCTION public.fn_get_branches_for_benchmarking(p_tenant_id uuid, p_organization_id uuid)  RETURNS TABLE(id uuid, name character varying, location character varying)  LANGUAGE sql  STABLE AS $function$     WITH org_branches AS (         SELECT b.id, b.name, COALESCE(b.location, 'Main Campus')::varchar AS location         FROM branches b         WHERE b.tenant_id = p_tenant_id            AND b.organization_id = p_organization_id           AND b.is_active = true         ORDER BY b.name     )     SELECT * FROM org_branches     UNION ALL     SELECT b.id, b.name, COALESCE(b.location, 'Main Campus')::varchar AS location     FROM branches b     WHERE b.tenant_id = p_tenant_id       AND b.is_active = true       AND NOT EXISTS (SELECT 1 FROM org_branches)     ORDER BY name; $function$ ;
